def run_tool_call(user, call, policy, sandbox):
    schema_validate(call["name"], call["args"])
    capability = policy.capability_for(call["name"])

    if capability in {"external_send", "money", "admin"}:
        approval = request_approval({
            "tool": call["name"],
            "args": call["args"],
            "risk": capability,
        })
        if not approval["approved"]:
            return {"status": "cancelled"}

    token = mint_scoped_token(user, call["name"], ttl_minutes=5)
    result = sandbox.execute(call, token=token, network=policy.egress(call))
    audit_log(user=user, call=call, result_digest=result["digest"], policy_version=policy.version)
    return result
